def _select_ready(readers,writers,exceptional,timeout):
 """Only existing pipe read/write readiness; no FD_SETSIZE restriction."""
 if exceptional:raise ValueError('copy_selector_exceptional_not_supported')
 registrations={}
 for values,event in ((readers,selectors.EVENT_READ),(writers,selectors.EVENT_WRITE)):
  for value in values:
   fd=value if type(value)is int else value.fileno()
   if type(fd)is not int or fd<0:raise ValueError('copy_selector_descriptor_unknown')
   registrations[fd]=registrations.get(fd,0)|event
 with selectors.DefaultSelector()as selector:
  for fd,event in registrations.items():selector.register(fd,event)
  events={key.fd:mask for key,mask in selector.select(timeout)}
  ready=lambda values,event:[value for value in values if events.get(value if type(value)is int else value.fileno(),0)&event]
  return ready(readers,selectors.EVENT_READ),ready(writers,selectors.EVENT_WRITE),[]

def collector(*,deadline_seconds=1250):
    if type(deadline_seconds)is not int or not 1<=deadline_seconds<=1250:
        raise ValueError('asset_collector_deadline_unknown')
    if hashlib.sha256(COLLECTOR_SOURCE.encode()).hexdigest()!=COLLECTOR_SOURCE_SHA256:
        raise ValueError('asset_operator_collector_source_changed')
    tree=ast.parse(COLLECTOR_SOURCE)
    namespace=dict(ast=ast,base64=base64,hashlib=hashlib,json=json,math=math,os=os,select=select,stat=stat,subprocess=subprocess,time=time,Path=Path)
    exec(compile(tree,'<source-bound-original-asset-collector>','exec',dont_inherit=True),namespace)
    embedded=ast.get_source_segment(COLLECTOR_SOURCE,next(n for n in tree.body if isinstance(n,ast.FunctionDef)and n.name=='collect'))
    if embedded.count('select.select(')!=2:raise ValueError('asset_collector_readiness_shape_changed')
    changed=embedded.replace('select.select(', '_select_ready(')
    before=ast.parse(embedded);reverse=ast.parse(changed)
    for node in ast.walk(reverse):
        if isinstance(node,ast.Call)and isinstance(node.func,ast.Name)and node.func.id=='_select_ready':
            node.func=ast.Attribute(value=ast.Name(id='select',ctx=ast.Load()),attr='select',ctx=ast.Load())
    if ast.dump(before)!=ast.dump(reverse):raise ValueError('asset_collector_readiness_semantics_changed')
    if deadline_seconds!=1250:
        # Bind execution and its durable handle to the same admitted deadline.
        # The authenticated default frame and every other literal stay exact.
        boundaries=(('        deadline=time.monotonic()+1250\n','        deadline=time.monotonic()+'+str(deadline_seconds)+'\n'),
                    ("capture.create('handle.json',encoded({'pid':process.pid,'started':time.time(),'deadlineSeconds':1250}))",
                     "capture.create('handle.json',encoded({'pid':process.pid,'started':time.time(),'deadlineSeconds':"+str(deadline_seconds)+"}))"))
        bounded=changed
        for old,new in boundaries:
            if bounded.count(old)!=1:raise ValueError('asset_collector_deadline_shape_changed')
            bounded=bounded.replace(old,new)
        restored=bounded
        for old,new in boundaries:
            if restored.count(new)!=1:raise ValueError('asset_collector_deadline_shape_changed')
            restored=restored.replace(new,old)
        if restored!=changed or ast.dump(ast.parse(restored))!=ast.dump(ast.parse(changed)):
            raise ValueError('asset_collector_deadline_semantics_changed')
        changed=bounded
    namespace['_select_ready']=_select_ready
    exec(compile(changed,'<canonical-asset-selector-collector>','exec',dont_inherit=True),namespace)
    # This is the currently authenticated embedded pre-selector frame.
    namespace['_embedded_collect_source']=embedded
    # Compatibility spelling used by earlier readiness controls. It refers to
    # that current frame, never the immutable historical baseline fixture.
    namespace['_historical_collect_source']=embedded
    namespace['_original_collect_source']=changed
    return namespace

def collect_asset(prepared,argv,stream,capture,*,source_custody=None):
    """Native-capable only after independent stream review+root explicit GO.

    Keep exact original select/timeout/raw-first/dualEOF collector. Only its
    stdin producer changes from one in-memory source to StreamPayload's fixed
    prefix and held nofollow file chunks. No input/key bytes are archived here.
    """
    if not callable(source_custody):
        raise ValueError('asset_operator_source_custody_required')
    source_custody()
    base=collector();source=base['_original_collect_source']
    changes={
        'def collect(state,credential):':'def collect_stream(state,credential):',
        "payload=bytearray(credential)+state['source'];credential=b''":"payload=bytearray(state['stream'].prefix);credential=b''",
        'if offset==len(payload):writer.close();writer=None;payload.clear()':"""if offset==len(payload):
                    payload.clear();offset=0
                    part=os.read(state['assetFd'],65536)
                    if part:
                        state['assetHash'].update(part);state['assetBytes']+=len(part)
                        if state['assetBytes']>state['payloadPin']['generation'][6]:raise ValueError('asset_operator_stream_changed')
                        payload.extend(part)
                    else:
                        if state['assetBytes']!=state['payloadPin']['generation'][6] or state['assetHash'].hexdigest()!=state['payloadPin']['sha256'] or assets.generation(os.fstat(state['assetFd']))!=state['payloadPin']['generation']:raise ValueError('asset_operator_stream_changed')
                        writer.close();writer=None""",
    }
    for old,new in changes.items():
        if source.count(old)!=1:raise ValueError('asset_operator_stream_boundary_changed')
        source=source.replace(old,new)
    base['assets']=assets
    exec(compile(source,'<actual-collector-fixed-StreamPayload>','exec',dont_inherit=True),base)
    pin=prepared['payloadPin']
    if stream.path!=Path(pin['path']) or type(stream.prefix)is not bytes or not stream.prefix or len(stream.prefix)>69632:raise ValueError('asset_operator_stream_binding_changed')
    with assets.held_custody([(pin,assets.MAX_TOTAL)])as closing:
        fd=os.open(stream.path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
        try:
            if assets.generation(os.fstat(fd))!=pin['generation']:raise ValueError('asset_operator_stream_changed')
            state={'argv':argv,'capture':capture,'stream':stream,'assetFd':fd,'payloadPin':pin,'assetHash':hashlib.sha256(),'assetBytes':0}
            # transport_request already produced durable submission intent. The
            # collector records original process PID/start before first write.
            # Fixed create-only attempt receipt survives loss of the launch
            # marker; neither a missing marker nor a new capture permits retry.
            attempt=Path(pin['path']).parent/'asset-collection-attempt.json'
            try:attempt_fd=os.open(attempt,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
            except FileExistsError:raise ValueError('asset_operator_collection_consumed')from None
            attempt_data=assets.canonical({'schema':1,'correlationId':prepared['correlationId'],'payloadSha256':pin['sha256'],'manifestSha256':prepared['manifestSha256'],'replayAllowed':False})
            try:
                at=0
                while at<len(attempt_data):
                    count=os.write(attempt_fd,attempt_data[at:])
                    if count<=0:raise ValueError('asset_operator_intent_write_unknown')
                    at+=count
                os.fsync(attempt_fd)
            finally:os.close(attempt_fd)
            attempt_pin=assets.snapshot(attempt,65536)
            if attempt_pin['sha256']!=assets.sha(attempt_data):raise ValueError('asset_operator_intent_changed')
            marker=Path(pin['path']).parent/'asset-collection-intent.json'
            try:once=os.open(marker,os.O_RDWR|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
            except FileExistsError:raise ValueError('asset_operator_collection_consumed')from None
            try:
                data=assets.canonical({'schema':1,'correlationId':prepared['correlationId'],'payloadSha256':pin['sha256'],'manifestSha256':prepared['manifestSha256'],'replayAllowed':False});at=0
                while at<len(data):
                    count=os.write(once,data[at:])
                    if count<=0:raise ValueError('asset_operator_intent_write_unknown')
                    at+=count
                os.fsync(once)
                directory=os.open(marker.parent,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
                try:os.fsync(directory)
                finally:os.close(directory)
                original=assets.generation(os.fstat(once));marker_pin=assets.snapshot(marker,65536)
                if marker_pin['generation']!=original or marker_pin['sha256']!=assets.sha(data):raise ValueError('asset_operator_intent_changed')
                with assets.held_custody([(marker_pin,65536),(attempt_pin,65536)])as once_closing:
                    def intent_closing():
                        try:
                            if assets.generation(os.fstat(once))!=original:raise ValueError('asset_operator_intent_changed')
                            once_closing()
                        except (ValueError,OSError):raise ValueError('asset_operator_intent_changed')from None
                    capture.create('asset-collection-intent.json',data)
                    closing();intent_closing();source_custody()
                    raw=base['collect_stream'](state,b'')
                    intent_closing();source_custody()
            finally:os.close(once)
            closing()
        finally:os.close(fd)
    result=assets.project(prepared,raw,b'',0,{'stdout':True,'stderr':True})
    capture.create('asset-custody-projection.json',assets.canonical(result))
    return result
